#!/usr/bin/env python3
"""
Round 165b (culprits), 4 October 2026. Needs round 158b.

Woodlands place names in the same theme.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 165b (4 October)\n\nNeeds round 158b. No tiles patch. No app.js?v= bump.\n\n- Owner: the place names in the Woodlands theme. On Woodlands, CARTO's grey\n  picture of names is hidden and names are drawn from OpenFreeMap's place,\n  water, river, road and peak names (10 layers, outline-wood-name-*,\n  WOOD_NAME_IDS) in EB Garamond from map/glyphs/, as Hell does (round 163h):\n  countries in spaced capitals of pale parchment (#E6D8AE), cities warm cream\n  (#F0E6C8), towns #E0D4B2, water in italic pale sage (#C3D4C4), on soft dark\n  forest-green haloes. Kept above the layers (woodNamesOnTop); the Place\n  names switch still works. Falls back to the grey picture if the map's\n  letters were set elsewhere.\n"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round165b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 158b" not in h.read_text(encoding="utf-8"):
        sys.exit("round165b: round 158b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round165b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round165b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round165b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
